package com.restaurantmanagement.security; import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import java.nio.charset.StandardCharsets; import java.util.*;
@Component public class JwtAuthenticationFilter extends OncePerRequestFilter { private final byte[] secret; public JwtAuthenticationFilter(@Value("${app.jwt.secret}") String s){secret=s.getBytes(StandardCharsets.UTF_8);} protected void doFilterInternal(HttpServletRequest r,HttpServletResponse p,FilterChain c)throws ServletException,java.io.IOException {String h=r.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer "))try{var claims=Jwts.parser().verifyWith(Keys.hmacShaKeyFor(secret)).build().parseSignedClaims(h.substring(7)).getPayload();var a=new SimpleGrantedAuthority("ROLE_"+claims.get("role",String.class));SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(claims.getSubject(),null,List.of(a)));}catch(JwtException ignored){} c.doFilter(r,p,c);} }
